const FONT_STORAGE_KEY="blogFontPreference",GOOGLE_SANS_CLASS="font-google-sans",bodyElement=document.body,togglerElement=document.getElementById("font-toggler"),FONT_NAME_1="Roboto",FONT_NAME_2="Google Sans Flex";function toggleFont(){bodyElement.classList.contains(GOOGLE_SANS_CLASS)?(bodyElement.classList.remove(GOOGLE_SANS_CLASS),localStorage.setItem(FONT_STORAGE_KEY,"Roboto")):(bodyElement.classList.add(GOOGLE_SANS_CLASS),localStorage.setItem(FONT_STORAGE_KEY,FONT_NAME_2))}function applySavedFont(){localStorage.getItem(FONT_STORAGE_KEY)===FONT_NAME_2&&bodyElement.classList.add(GOOGLE_SANS_CLASS),togglerElement&&togglerElement.addEventListener("click",toggleFont)}applySavedFont();